void setup() {
  pinMode(3, OUTPUT);
}
void loop() {
  digitalWrite(3, HIGH);
  delay(500);
  digitalWrite(3, LOW);
  delay(500);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  int pressed = digitalRead(2) == LOW;
  digitalWrite(3, pressed);
  Serial.println(pressed);
  delay(20);
}

void setup() {
  pinMode(3, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  int value = analogRead(A0);
  int pwm = (value - value % 4) / 4;
  analogWrite(3, pwm);
  Serial.println(value);
  delay(50);
}
